class Solution:
    def findMaxLength(self, nums: List[int]) -> int:
        first = {0: -1}                          # prefix sum -> earliest index
        total = best = 0
        for i, x in enumerate(nums):
            total += 1 if x == 1 else -1         # treat 0 as -1
            if total in first:
                best = max(best, i - first[total])
            else:
                first[total] = i
        return best
